package com.codeguardian.controller; import com.codeguardian.dto.PermissionDTO; import com.codeguardian.entity.Permission; import com.codeguardian.service.PermissionService; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Controller; import org.springframework.web.bind.annotation.*; import java.util.List; @Controller @RequestMapping("/admin/permissions") @RequiredArgsConstructor public class PermissionController{private final PermissionService service; @GetMapping public String page(){return "admin/permissions";} @GetMapping("/api") @ResponseBody public List<Permission> all(){return service.getAllPermissions();} @GetMapping("/api/dto") @ResponseBody public List<PermissionDTO> dto(){return service.getAllPermissionDTOs();}}
